mapper.select:
SELECT COUNT(1)
FROM pisces_event_materialization
WHERE fact_kind = #{factKind}
  AND fact_id = #{factId}

SELECT COUNT(1)
FROM pisces_experiment_event e
INNER JOIN pisces_event_materialization m
  ON m.fact_kind = 'EVENT'
 AND m.fact_id = e.event_id
 AND m.experiment_id = e.experiment_id
 AND m.group_id = e.group_id
WHERE e.experiment_id = #{experimentId}
  AND e.group_id = #{groupId}

  AND e.event_time >= #{startTime}


  AND e.event_time <= #{endTime}


  AND e.event_type IN

    #{eventType}

SELECT COUNT(1)
FROM pisces_experiment_exposure x
INNER JOIN pisces_event_materialization m
  ON m.fact_kind = 'EXPOSURE'
 AND m.fact_id = x.exposure_id
 AND m.experiment_id = x.experiment_id
 AND m.group_id = x.group_id
WHERE x.experiment_id = #{experimentId}
  AND x.group_id = #{groupId}

  AND x.exposed_at >= #{startTime}


  AND x.exposed_at <= #{endTime}
